"""Generate the next order ID from ids.txt.

Order IDs have the form ORD- followed by four base36 characters.
The most recent ID is on the last non-empty line of ids.txt.
"""


def to_base36(n, width=4):
    """Format an integer as a zero-padded uppercase base36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0" * width
    result = ""
    while n:
        n, rem = divmod(n, 36)
        result = chars[rem] + result
    return result.rjust(width, "0")


def next_order_id(ids_path="ids.txt"):
    """Return the next order id given the ids file's last id."""
    last_id = None
    with open(ids_path, encoding="utf-8") as fh:
        for line in fh:
            candidate = line.strip()
            if candidate:
                last_id = candidate

    if last_id is None:
        raise ValueError("ids.txt contains no order ids")

    prefix, sep, suffix = last_id.partition("-")
    if prefix != "ORD" or not sep or len(suffix) != 4:
        raise ValueError(f"unrecognized order id format: {last_id!r}")

    suffix = suffix.upper()
    try:
        n = int(suffix, 36) + 1
    except ValueError:
        raise ValueError(f"invalid base36 suffix: {suffix!r}")

    return f"ORD-{to_base36(n, width=4)}"


if __name__ == "__main__":
    print(next_order_id())
