import sys


BASE = 36
DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
ID_PREFIX = "ORD-"
SUFFIX_LEN = 4


def to_base36(number: int) -> str:
    if number == 0:
        return DIGITS[0]
    chars = []
    while number:
        number, rem = divmod(number, BASE)
        chars.append(DIGITS[rem])
    return "".join(reversed(chars))


def from_base36(text: str) -> int:
    value = 0
    for char in text:
        value = value * BASE + DIGITS.index(char)
    return value


def next_id(ids_path: str) -> str:
    with open(ids_path, encoding="utf-8") as fh:
        lines = [line.strip() for line in fh if line.strip()]
    last = lines[-1]
    suffix = last[len(ID_PREFIX):]
    suffix = suffix.upper()
    number = from_base36(suffix)
    return ID_PREFIX + to_base36(number + 1).rjust(SUFFIX_LEN, "0")


def main() -> None:
    print(next_id("ids.txt"))


if __name__ == "__main__":
    main()

