#!/usr/bin/env python3
"""Read attendees.txt, sort names alphabetically, write roster.txt."""

with open('attendees.txt', encoding='utf-8') as f:
    names = []
    for line in f:
        line = line.strip()
        if not line:
            continue
        # If line contains a tab, take the part after it as the name
        if '\t' in line:
            name = line.split('\t', 1)[1].strip()
        else:
            name = line
        if name:
            names.append(name)

names.sort()

with open('roster.txt', 'w', encoding='utf-8') as f:
    for name in names:
        f.write(name + '\n')

