#!/usr/bin/env python3
"""Read entries.txt (key=value per line) and write config.json."""

import json

def main():
    config = {}
    with open("entries.txt") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            key, _, value = line.partition("=")
            key = key.strip()
            value = value.strip()
            if key:
                config[key] = value

    with open("config.json", "w") as f:
        json.dump(config, f, indent=2)
        f.write("\n")

if __name__ == "__main__":
    main()

