"""Generate manifest.json mapping release/ files to SHA-256 hex digests."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with filepath.open("rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    for entry in sorted(RELEASE_DIR.rglob("*")):
        if entry.is_file():
            # Relative path from repo root, using forward slashes
            rel_path = str(entry.relative_to(REPO_ROOT))
            manifest[rel_path] = sha256_digest(entry)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

