#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}
    for root, _dirs, files in os.walk(RELEASE_DIR):
        for name in sorted(files):
            filepath = Path(root) / name
            rel_path = str(filepath.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(filepath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

