#!/usr/bin/env python3
"""List report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(__file__), "reports")


def report_sort_key(name: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    m = re.search(r"(\d+)", name)
    return int(m.group(1)) if m else 0


def main() -> None:
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    # Filter to files matching report-N.txt and sort numerically
    reports = [f for f in files if re.match(r"^report-\d+\.txt$", f)]
    reports.sort(key=report_sort_key)

    for name in reports:
        print(name)


if __name__ == "__main__":
    main()

