REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_sort_key(filename: str) -> tuple:
    """Extract numeric parts for natural sort order of report filenames."""
    parts = re.split(r"(\d+)", filename)
    return tuple(int(p) if p.isdigit() else p for p in parts)


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: {REPORTS_DIR} not found")
        return

    # Filter to only regular files (skip directories, etc.)
    files = [e for e in entries if os.path.isfile(os.path.join(REPORTS_DIR, e))]
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

