#!/usr/bin/env python3
"""Count word frequencies across all .txt files under docs/."""

import os
from collections import Counter

PUNCTUATION = '.,;:!?'
DOCS_DIR = 'docs'
OUTPUT_FILE = 'counts.txt'


def strip_punctuation(word):
    """Strip punctuation characters .,;:!? from word edges."""
    return word.strip(PUNCTUATION)


def main():
    counter = Counter()

    # Walk through docs/ looking for .txt files
    for entry in os.scandir(DOCS_DIR):
        if entry.is_file() and entry.name.endswith('.txt'):
            with open(entry.path, encoding='utf-8') as f:
                for line in f:
                    for raw_word in line.split():
                        word = strip_punctuation(raw_word.lower())
                        if word:
                            counter[word] += 1

    # Write output sorted alphabetically by word
    with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
        for word in sorted(counter):
            f.write(f'{word} {counter[word]}\n')


if __name__ == '__main__':
    main()

